// Verified model loading for on-device mode (tasks D7 + E1).
//
// * lib/models.manifest.json (generated by scripts/model-manifest.mjs, shipped in the app bundle) lists the SHA-256
//   of every model file. Each download is hashed with WebCrypto and rejected unless it matches, so a compromised
//   CDN or a tampered cache entry cannot inject a model.
// * Verified files are kept in the Cache API under a name that includes the manifest version; caches from older
//   versions are deleted. A warm start reads everything from the cache and makes no network request.
import manifest from "./models.manifest.json" with { type: "json" };

export interface ModelFile { sha256: string; bytes: number }
export interface ModelEntry { kind: string; licence: string; megabytes: number; files: Record<string, ModelFile> }
export const MANIFEST = manifest as { version: string; models: Record<string, ModelEntry> };
export const CACHE_PREFIX = "redactd-models-";
export const CACHE_NAME = CACHE_PREFIX + MANIFEST.version;
export const hasModel = (id: string) => !!MANIFEST.models[id] && Object.keys(MANIFEST.models[id].files).some((f) => f.endsWith(".onnx"));
export const modelMegabytes = (ids: string[]) => Math.round(ids.reduce((a, id) => a + (MANIFEST.models[id]?.megabytes ?? 0), 0));

const hex = (buf: ArrayBuffer) => Array.from(new Uint8Array(buf), (b) => b.toString(16).padStart(2, "0")).join("");
export async function sha256(buf: ArrayBuffer): Promise<string> { return hex(await crypto.subtle.digest("SHA-256", buf)); }

export class IntegrityError extends Error {}

/** Fetch one model file, verify it, cache it. Returns the verified bytes. */
export async function verifiedFile(base: string, model: string, file: string, onBytes?: (n: number) => void): Promise<ArrayBuffer> {
  const want = MANIFEST.models[model]?.files[file];
  if (!want) throw new IntegrityError(`${model}/${file} is not in the model manifest`);
  const url = new URL(`${base}${model}/${file}`, self.location.href).href;
  const cache = typeof caches !== "undefined" ? await caches.open(CACHE_NAME).catch(() => null) : null;
  const hit = await cache?.match(url);
  if (hit) {
    const buf = await hit.arrayBuffer();
    if (buf.byteLength === want.bytes && (await sha256(buf)) === want.sha256) { onBytes?.(buf.byteLength); return buf; }
    await cache!.delete(url);      // corrupted or tampered cache entry: download again
  }
  const r = await fetch(url, { cache: "no-store", credentials: "omit" });
  if (!r.ok || !r.body) throw new Error(`could not download ${model}/${file} (${r.status})`);
  const reader = r.body.getReader(), chunks: Uint8Array[] = [];
  let n = 0;
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    chunks.push(value); n += value.byteLength; onBytes?.(value.byteLength);
    if (n > want.bytes) { await reader.cancel(); throw new IntegrityError(`${model}/${file} is larger than the manifest says`); }
  }
  const buf = new Uint8Array(n);
  let off = 0;
  for (const c of chunks) { buf.set(c, off); off += c.byteLength; }
  if ((await sha256(buf.buffer)) !== want.sha256) throw new IntegrityError(`${model}/${file} failed its integrity check and was not loaded`);
  await cache?.put(url, new Response(buf.buffer, { headers: { "Content-Type": "application/octet-stream", "Content-Length": String(n) } })).catch(() => {});
  return buf.buffer;
}

/** Download + verify every file of the given models (with byte-level progress) and drop caches of older versions. */
export async function prepareModels(base: string, ids: string[], onProgress?: (done: number, total: number) => void): Promise<Map<string, ArrayBuffer>> {
  if (typeof caches !== "undefined") for (const k of await caches.keys().catch(() => [] as string[])) if (k.startsWith(CACHE_PREFIX) && k !== CACHE_NAME) await caches.delete(k);
  const total = ids.reduce((a, id) => a + Object.values(MANIFEST.models[id]?.files ?? {}).reduce((x, f) => x + f.bytes, 0), 0);
  let done = 0;
  const out = new Map<string, ArrayBuffer>();
  for (const id of ids) {
    if (!MANIFEST.models[id]) throw new Error(`model ${id} is not available in this build`);
    for (const file of Object.keys(MANIFEST.models[id].files))
      out.set(`${id}/${file}`, await verifiedFile(base, id, file, (n) => { done += n; onProgress?.(Math.min(done, total), total); }));
  }
  return out;
}

/** Cache adapter for transformers.js: it may only read files that prepareModels() verified. */
export function verifiedCache(base: string, files: Map<string, ArrayBuffer>) {
  const key = (req: string | Request | URL) => {
    const u = typeof req === "string" ? req : req instanceof URL ? req.href : req.url;
    const abs = new URL(u, self.location.href).href, root = new URL(base, self.location.href).href;
    return abs.startsWith(root) ? abs.slice(root.length) : null;
  };
  return {
    async match(req: string | Request | URL): Promise<Response | undefined> {
      const k = key(req), buf = k ? files.get(k) : undefined;
      // unknown files answer 404 from the "cache", so the library never falls back to an unverified network read
      return buf ? new Response(buf.slice(0), { headers: { "Content-Length": String(buf.byteLength) } }) : new Response(null, { status: 404 });
    },
    async put(): Promise<void> { /* already cached, verified, by prepareModels */ },
  };
}
